CREATE COLUMN TABLE "TEST_AP"."ALR1" ("Code" INTEGER CS_INT NOT NULL , "LineId" INTEGER CS_INT NOT NULL , "NameFrom" NVARCHAR(155), "AddrFrom" NVARCHAR(100), "NameTo" NVARCHAR(155), "IsSMS" NVARCHAR(1) DEFAULT 'N', "Address" NVARCHAR(100), "Status" NVARCHAR(1) DEFAULT 'U', "ObjType" NVARCHAR(20), "ObjCode" NVARCHAR(50), PRIMARY KEY ("Code", "LineId")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "ALR1_STATUS" ON "TEST_AP"."ALR1" ( "Status" ASC )